// ADS1115 at 0x48 (ADDR tied to GND): read AIN0 against GND, +-4.096 V range, one-shot
const ADDR = 0x48;
// OS=1 (start), MUX=100 (AIN0/GND), PGA=001 (+-4.096 V), MODE=1 (single-shot), DR=100 (128 SPS), comparator off
const cfg = (1 << 15) | (0b100 << 12) | (0b001 << 9) | (1 << 8) | (0b100 << 5) | 0b11;
i2c.writeReg16(ADDR, 0x01, cfg);
delay(10); // 128 SPS is about 7.8 ms per conversion

log('Config now =', hex(i2c.readReg16(ADDR, 0x01)), '(bit 15 set = conversion finished)');
const code = toInt16(i2c.readReg16(ADDR, 0x00));
log('code =', code, '->', (code * 125e-6).toFixed(4), 'V  (125 uV per count at +-4.096 V)');
